// random.js — one seeded number stream, and the little helpers the generators want from it.
//
// Everything that is laid out at load — the block plan, the skyline, the fleet, the crowd, the lit
// windows — is drawn from a stream built here, so `?seed=4` produces the same town on every machine
// and a staged photograph is identical each time it is taken. The generator is mulberry32: a
// 32-bit counter, a couple of multiply-xor rounds, a division. One integer of state, reproducible
// from the seed alone, which is why a seed can be passed to a module and replayed later.

/** A random stream. Call it for a float in [0, 1); it also carries a few shape helpers. */
export function stream(seed = 1) {
  let state = (Math.imul(seed | 0, 0x9e3779b1) ^ 0x85ebca6b) >>> 0;
  if (state === 0) state = 0x6d2b79f5;

  const next = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  /** A float in [lo, hi). */
  next.between = (lo, hi) => lo + next() * (hi - lo);
  /** An integer in [lo, hi], both ends included. */
  next.int = (lo, hi) => Math.floor(lo + next() * (hi - lo + 1));
  /** One member of a list. */
  next.pick = (list) => list[Math.min(list.length - 1, Math.floor(next() * list.length))];
  /** True with probability p. */
  next.chance = (p = 0.5) => next() < p;
  /** Either -1 or 1. */
  next.sign = () => (next() < 0.5 ? -1 : 1);

  return next;
}
