    const line = rand.pick(AVENUES);
    const along = Math.floor(rand.between(low, high) / 40) * 40 + 20;
    if (inJunction(along)) continue;
    const kind = rand.pick(['sedan', 'sedan', 'coupe', 'suv', 'cab', 'sedan', 'drop', 'van', 'coupe']);
