      const ahead = (onFoot.x - car.x) * car.dir.dx + (onFoot.z - car.z) * car.dir.dz;
      const side = Math.abs((onFoot.x - car.x) * car.dir.dz - (onFoot.z - car.z) * car.dir.dx);
      if (ahead > 0 && side < 2.4) gap = Math.min(gap, ahead - 3);
